//! Differential operator fixtures generated by the pinned PyPhi GID corpus.
//!
//! These tests qualify the pointwise GID operator only. They do not claim
//! partition, MIP, or end-to-end IIT system-search parity.

use symthaea_iit::{
    generalized_intrinsic_difference,
    generalized_intrinsic_difference_at_state,
};

struct GidCase {
    id: &'static str,
    forward: &'static [f64],
    partitioned: &'static [f64],
    selectivity: &'static [f64],
    expected: &'static [f64],
}

const CASES: &[GidCase] = &[
    GidCase {
        id: "mixed-sign-ratios",
        forward: &[0.5, 0.25, 0.125, 0.125],
        partitioned: &[0.25, 0.5, 0.25, 0.25],
        selectivity: &[0.4, 0.3, 0.2, 0.1],
        expected: &[0.4, -0.3, -0.2, -0.1],
    },
    GidCase {
        id: "one-sided-and-both-zero-support",
        forward: &[0.5, 0.0, 0.25, 0.0],
        partitioned: &[0.25, 0.5, 0.0, 0.0],
        selectivity: &[0.4, 0.3, 0.2, 0.1],
        expected: &[0.4, 0.0, 0.0, 0.0],
    },
    GidCase {
        id: "equal-repertoires",
        forward: &[0.25, 0.5, 0.25],
        partitioned: &[0.25, 0.5, 0.25],
        selectivity: &[0.2, 0.5, 0.3],
        expected: &[0.0, 0.0, 0.0],
    },
    GidCase {
        id: "rare-but-representable",
        forward: &[1.0e-200, 2.0e-200, 4.0e-200],
        partitioned: &[2.0e-200, 1.0e-200, 2.0e-200],
        selectivity: &[0.2, 0.3, 0.5],
        expected: &[-0.2, 0.3, 0.5],
    },
    GidCase {
        id: "nonuniform-weighting",
        forward: &[0.8, 0.1, 0.05, 0.05],
        partitioned: &[0.4, 0.2, 0.1, 0.1],
        selectivity: &[0.1, 0.2, 0.3, 0.4],
        expected: &[0.1, -0.2, -0.3, -0.4],
    },
];

fn assert_close(case_id: &str, index: usize, actual: f64, expected: f64) {
    assert!(actual.is_finite(), "{case_id}[{index}] is non-finite: {actual}");
    assert_eq!(
        actual == 0.0,
        expected == 0.0,
        "{case_id}[{index}] support mismatch: actual={actual:?}, expected={expected:?}",
    );
    assert!(
        (actual - expected).abs() <= 2.0e-14,
        "{case_id}[{index}] actual={actual:.17}, expected={expected:.17}",
    );
}

#[test]
fn pinned_pyphi_gid_operator_vectors_match_rust() {
    let mut state_count = 0usize;
    for case in CASES {
        let actual = generalized_intrinsic_difference(
            case.forward,
            case.partitioned,
            case.selectivity,
        )
        .unwrap_or_else(|error| panic!("{}: {error}", case.id));

        assert_eq!(actual.len(), case.expected.len(), "{} length", case.id);
        for (index, (actual, expected)) in actual.iter().zip(case.expected).enumerate() {
            assert_close(case.id, index, *actual, *expected);
            let at_state = generalized_intrinsic_difference_at_state(
                case.forward,
                case.partitioned,
                case.selectivity,
                index,
            )
            .unwrap_or_else(|error| panic!("{} state {index}: {error}", case.id));
            assert_close(case.id, index, at_state, *expected);
            state_count += 1;
        }
    }
    assert_eq!(CASES.len(), 5);
    assert_eq!(state_count, 18);
}

#[test]
fn gid_operator_fails_closed_on_invalid_selectivity_and_length_mismatch() {
    use symthaea_iit::RepertoireError;

    assert!(matches!(
        generalized_intrinsic_difference(&[0.5, 0.5], &[0.5], &[0.5, 0.5]),
        Err(RepertoireError::DistributionLengthMismatch { .. })
    ));
    assert!(matches!(
        generalized_intrinsic_difference(&[0.5, 0.5], &[0.5, 0.5], &[0.2, 0.2]),
        Err(RepertoireError::DistributionNotNormalized { .. })
    ));
}
